const clamp=(value,min,max)=>Math.max(min,Math.min(max,value));
const clone=value=>structuredClone(value);
const id=(prefix="id")=>`${prefix}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,8)}`;
const total=object=>Object.values(object||{}).reduce((sum,value)=>sum+Math.max(0,Number(value)||0),0);
const mergeDefaults=(base,input)=>{
  if(Array.isArray(base)) return Array.isArray(input)?input:clone(base);
  if(base&&typeof base==="object"){
    const source=input&&typeof input==="object"&&!Array.isArray(input)?input:{};
    return Object.fromEntries(Object.entries(base).map(([key,value])=>[key,mergeDefaults(value,source[key])]).concat(Object.entries(source).filter(([key])=>!(key in base))));
  }
  return input===undefined||input===null?base:input;
};

export const levelForXp=xp=>clamp(1+Math.floor(Math.sqrt(Math.max(0,xp)/100)),1,18);
export const xpForLevel=level=>Math.pow(Math.max(0,level-1),2)*100;
export const levelTitle=level=>[...LEVEL_TITLES].reverse().find(([required])=>level>=required)?.[1]||"Stand Starter";

const initialTrees=()=>Array.from({length:6},(_,index)=>({id:`apple-tree-${index+1}`,fruit:"apple",status:"ripe",readyAt:0,watered:false,fertilized:false,diseased:false,golden:false,x:26+(index%3)*5,y:61+Math.floor(index/3)*7,harvests:0}));
const initialDistricts=()=>Object.fromEntries(DISTRICTS.map((district,index)=>[district.id,{unlocked:index<2,upgrades:[],crateFound:false,teleporter:false,visits:0}]));
const initialFruit=()=>Object.fromEntries(FRUITS.map(fruit=>[fruit.id,0]));
const initialProducts=()=>Object.fromEntries(RECIPES.map(recipe=>[recipe.id,0]));
const initialQualities=()=>Object.fromEntries(FRUITS.map(fruit=>[fruit.id,fruit.id==="apple"?1:0]));
const initialDiscovered=()=>Object.fromEntries(FRUITS.map(fruit=>[fruit.id,fruit.id==="apple"]));
const initialApplicants=()=>Object.fromEntries(WORKERS.slice(1).map((worker,index)=>[worker.id,{workerId:worker.id,status:index===0?"applied":"prospect",relationship:0,information:15,comfort:40,suitability:0,interest:35,professionalism:50,notes:"",referenceChecked:false,trial:null,interview:null,offer:null,hiddenTalent:index%3===0?worker.specialAbility:null,favor:index%4===0?"Craft their favorite product":""}]));
const initialSewer=()=>({
  unlocked:false,active:false,lastEntrance:null,surfacePosition:null,player:{x:8,y:76,section:"drainage-entrance"},
  entrances:Object.fromEntries(SEWER_ENTRANCES.map((entry,index)=>[entry.id,{discovered:false,open:false,symbolRead:false,listened:false,first:index===0}])),
  inventory:Object.fromEntries(SEWER_ITEMS.map(item=>[item.id,0])),samples:[],collectionPoints:Object.fromEntries(WATER_POINTS.map(point=>[point.id,{readyAt:0,collections:0}])),
  lab:{discovered:false,activeExperiment:null,history:[],recipes:{},machineLevel:1,rareFruitUntil:0},
  maze:{atEntrance:false,mapStudied:false,centerReached:false,mafiaSymbol:false,valves:Object.fromEntries(SEWER_VALVES.map(valve=>[valve.id,false])),valveSequence:[],gates:Object.fromEntries(SEWER_GATES.map(gate=>[gate.id,false])),shortcuts:Object.fromEntries(SEWER_SHORTCUTS.map(shortcut=>[shortcut.id,false])),treasures:Object.fromEntries(SEWER_TREASURES.map(treasure=>[treasure.id,false])),landmarks:[],aids:{}},
  characters:Object.fromEntries(SEWER_CHARACTERS.map(character=>[character.id,{met:false,tasks:[],dialogue:[],messageSent:false}])),
  quests:Object.fromEntries(SEWER_QUESTS.map(quest=>[quest.id,{completed:false,claimed:false}])),
  secrets:Object.fromEntries(SEWER_SECRETS.map(secret=>[secret.id,{clues:0,discovered:false}])),
  mafia:{invitation:false,membership:false,reputation:0,clubChips:0,joinedAt:0},
  plinko:{history:[],pending:null,playsToday:0,playDay:"",freeDropDay:"",jackpots:0},
  slots:{history:[],pending:null,playsToday:0,playDay:""},
  futureGame:{...FUTURE_MAFIA_GAME},mafiaGame:createDefaultMafiaGameState(),stats:{waterCollected:0,experiments:0,recipes:0,treasures:0,plinko:0,slots:0,mafiaRounds:0}
});

