  collectGreenWater(pointId,containerId){const point=WATER_POINT_BY_ID[pointId],container=SEWER_CONTAINER_BY_ID[containerId],progress=this.state.sewer.collectionPoints[pointId];if(!point||!progress)return this.result(false,"Water collection point not found.");if(!container)return this.result(false,"Select a valid sewer-water container.");if((this.state.sewer.inventory[containerId]||0)<1)return this.result(false,`Obtain a ${container.name} before collecting water.`);const occupied=this.state.sewer.samples.filter(sample=>!sample.consumed&&sample.containerId===containerId).length,capacity=(this.state.sewer.inventory[containerId]||0)*container.capacity;if(occupied>=capacity)return this.result(false,`Every ${container.name} is currently full. Use a sample in the Test Lab first.`);if(progress.readyAt>this.now)return this.result(false,`${Math.ceil((progress.readyAt-this.now)/1000)} seconds until this water source respawns.`);const sample={id:id("water"),pointId,waterId:point.water,quality:point.quality,containerId,collectedAt:this.now,consumed:false};this.state.sewer.samples.push(sample);progress.collections++;progress.readyAt=this.now+point.cooldown*1000;this.state.sewer.stats.waterCollected++;this.completeSewerQuest("collect-green-water");if(["ancient-pipe-water","cosmic-green-water"].includes(point.water))this.completeSewerQuest("collect-rare-water");return this.result(true,`${container.name} filled with ${point.quality}. It will respawn in ${point.cooldown} seconds.`,{sample});}
  startSewerExperiment({sampleId,ingredient,additional="",intensity="normal",duration="standard",purify=false}={}){const sewer=this.state.sewer,lab=sewer.lab;if(!lab.discovered)return this.result(false,"Discover the Sewer Test Lab before experimenting.");if(lab.activeExperiment&&!lab.activeExperiment.collected)return this.result(false,"Collect the current experiment before starting another.");const sample=sewer.samples.find(item=>item.id===sampleId&&!item.consumed);if(!sample)return this.result(false,"Select a filled Green Sewer Water sample.");const sourceFor=item=>FRUIT_BY_ID[item]?this.state.fruitInventory:RECIPE_BY_ID[item]?this.state.productInventory:SEWER_ITEM_BY_ID[item]?sewer.inventory:null;const needs=[ingredient,additional].filter(Boolean);if(!ingredient)return this.result(false,"Choose a fruit or sewer ingredient.");for(const item of needs){const source=sourceFor(item);if(!source||(source[item]||0)<1)return this.result(false,`Need 1 ${FRUIT_BY_ID[item]?.name||RECIPE_BY_ID[item]?.name||SEWER_ITEM_BY_ID[item]?.name||item}.`);}if(purify&&this.state.researchPoints<2)return this.result(false,"Need 2 Research Points to purify the mixture.");for(const item of needs)sourceFor(item)[item]--;if(purify)this.state.researchPoints-=2;sample.consumed=true;const effectiveWater=purify?"filtered-sewer-water":sample.waterId,recipe=SEWER_RECIPES.find(item=>item.ingredient===ingredient&&(item.water==="any-green"||item.water===effectiveWater));const successChance={gentle:.9,normal:.82,wild:.68}[intensity]||.82,success=Boolean(recipe&&this.random()<successChance);let result=success?recipe.result:"funny-sludge",kind="item";if(!recipe){const roll=this.random();if(roll<.22){result="research-points";kind="research";}else if(roll<.34){result="maze-clue";kind="clue";}else if(roll<.4){result="fruit-mafia-invitation";kind="item";}}
    const seconds=({quick:12,standard:24,careful:38}[duration]||24)*(intensity==="wild"?.75:intensity==="gentle"?1.25:1),experiment={id:id("sewer-experiment"),sample:{...sample},ingredient,additional,intensity,duration,purified:purify,recipeId:success?recipe.id:null,result,kind,success,startedAt:this.now,readyAt:this.now+seconds*1000,status:"bubbling",collected:false};lab.activeExperiment=experiment;return this.result(true,`The mixing machine is bubbling for ${Math.ceil(seconds)} seconds.`,{experiment});}
